import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);
        int[] l = new int[n];
        String[] inputLine = br.readLine().split(" ");
        for (int i = 0; i < n; i++) {
            l[i] = Integer.parseInt(inputLine[i]);
        }

        int[] first = Arrays.copyOfRange(l, 0, n / 2);
        int[] sec = Arrays.copyOfRange(l, n / 2, n);

        int n1 = n / 2;
        int n2 = n / 2 + (n % 2);

        int t1 = 1 << n1;
        int t2 = 1 << n2;

        List<Integer> s1 = new ArrayList<>();
        for (int i = 0; i < t1; i++) {
            int now = 0;
            for (int j = 0; j < first.length; j++) {
                if ((i & (1 << j)) != 0) {
                    now += first[j];
                }
            }
            s1.add(now % m);
        }

        List<Integer> s2 = new ArrayList<>();
        for (int i = 0; i < t2; i++) {
            int now = 0;
            for (int j = 0; j < sec.length; j++) {
                if ((i & (1 << j)) != 0) {
                    now += sec[j];
                }
            }
            s2.add(now % m);
        }

        Collections.sort(s1);
        Collections.sort(s2);

        int maxi = 0;

        // Function to find the largest number less than x in sorted list l
        // equivalent to the `check` function in Python
        // Implemented as a helper method
        class Helper {
            int check(List<Integer> l, int x) {
                int lo = 0;
                int hi = l.size() - 1;
                int ans = 0;
                while (lo <= hi) {
                    int mi = (lo + hi) >> 1;
                    if (l.get(mi) < x) {
                        ans = l.get(mi);
                        lo = mi + 1;
                    } else {
                        hi = mi - 1;
                    }
                }
                return ans;
            }
        }

        Helper helper = new Helper();

        for (int i : s1) {
            int req = m - i;
            int pair = helper.check(s2, req);
            maxi = Math.max(maxi, (i + pair) % m);
        }

        System.out.println(maxi);
    }
}
